const revision = await $`git rev-parse --short HEAD`
  .timeout('10s')
  .text();

console.log(revision.trim());

import { $ } from '@xec-sh/core';

const remote = $.ssh({
  host: 'build.example.com',
  username: 'deploy',
});
const result = await remote`uname -a`.timeout('15s');
console.log(result.stdout);

import { $ } from '@xec-sh/core';

const container = $.docker({
  image: 'node:24',
});
const result = await container`node --version`;
console.log(result.stdout);

import { $ } from '@xec-sh/core';

const pod = $.k8s({
  namespace: 'staging',
  pod: 'api-pod',
  container: 'api',
});
const result = await pod`node --version`;
console.log(result.stdout);

import { Pipeline } from '@xec-sh/ops';

const result = await Pipeline.create('verify')
  .step('install', { run: 'pnpm install --frozen-lockfile' })
  .step('types', { run: 'pnpm typecheck', dependsOn: ['install'] })
  .step('tests', { run: 'pnpm test', dependsOn: ['install'] })
  .step('build', { run: 'pnpm build', dependsOn: ['types', 'tests'] })
  .run();

if (!result.success) throw new Error('Verification failed');

import { select, isCancel, log } from '@xec-sh/kit';

const target = await select({
  message: 'Choose a target',
  options: [
    { value: 'staging', label: 'Staging' },
    { value: 'production', label: 'Production' },
  ],
});

if (!isCancel(target)) log.info(`Selected: ${target}`);
